record UpdateProductRequest(String nameOrNull, BigDecimal priceOrNull) {}
static Product applyUpdate(Product existing, UpdateProductRequest req) {
  String newName = req.nameOrNull() != null ? req.nameOrNull() : existing.name();
  BigDecimal newPrice = req.priceOrNull() != null ? req.priceOrNull() : existing.price();
  return new Product(existing.id(), newName, newPrice, existing.costPrice());
}

