class CreateProductRequestValidator {
  static List<String> validate(CreateProductRequest req) {
    List<String> errors = new ArrayList<>();
    if (req.name() == null || req.name().isBlank()) errors.add("nazwa nie moze byc pusta");
    if (req.price().compareTo(BigDecimal.ZERO) <= 0) errors.add("cena musi byc dodatnia");
    return errors;
  }
}

