record OrderItem(String productName, int quantity, BigDecimal price) {}
record OrderItemResponse(String productName, int quantity) {}
record OrderResponse(long id, List<OrderItemResponse> items) {}
static OrderResponse toResponse(Order order) {
  List<OrderItemResponse> items = order.items().stream().map(i -> new OrderItemResponse(i.productName(), i.quantity())).toList();
  return new OrderResponse(order.id(), items);
}

