}

static List<Order> savedOrders = new ArrayList<>();
static OrderResponse handleCreateOrder(CreateOrderRequest req) {
  validate(req);
  Order order = new Order(savedOrders.size() + 1L, req.items());
  savedOrders.add(order);
  return toResponse(order);
}

