record PublicUserResponse(long id, String maskedEmail) {}
static String maskEmail(String email) {
  int at = email.indexOf('@');
  return email.charAt(0) + "***" + email.substring(at);
}
static PublicUserResponse toPublicResponse(User user) { return new PublicUserResponse(user.id(), maskEmail(user.email())); }

static BulkCreateUsersResponse processBulk(BulkCreateUsersRequest bulkRequest) {
  List<UserResponse> created = new ArrayList<>();
  List<String> errors = new ArrayList<>();
  for (CreateUserRequest req : bulkRequest.requests()) {
    try { created.add(toResponse(createUserFromRequest(req))); }
    catch (Exception e) { errors.add(req.email() + ": " + e.getMessage()); }
  }
  return new BulkCreateUsersResponse(created, errors);
}

